const projectDaemons = `-- name: ProjectDaemons :many
select d.token_id, d.hostname, d.version, d.last_seen_at, t.name as token_name
from agent_daemons d join agent_tokens t on t.id = d.token_id
where d.project_id = $1 and t.revoked_at is null
order by d.last_seen_at desc
`

type ProjectDaemonsRow struct {
	TokenID    int64
	Hostname   string
	Version    string
	LastSeenAt pgtype.Timestamptz
	TokenName  string
}

func (q *Queries) ProjectDaemons(ctx context.Context, projectID int64) ([]ProjectDaemonsRow, error) {
	rows, err := q.db.Query(ctx, projectDaemons, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProjectDaemonsRow{}
	for rows.Next() {
		var i ProjectDaemonsRow
		if err := rows.Scan(
			&i.TokenID,
			&i.Hostname,
			&i.Version,
			&i.LastSeenAt,
			&i.TokenName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

