const touchDaemon = `-- name: TouchDaemon :exec
insert into agent_daemons (token_id, project_id, hostname, version, last_seen_at)
values ($1, $2, $3, $4, now())
on conflict (token_id) do update
  set hostname = excluded.hostname, version = excluded.version, last_seen_at = now()
`

type TouchDaemonParams struct {
	TokenID   int64
	ProjectID int64
	Hostname  string
	Version   string
}

func (q *Queries) TouchDaemon(ctx context.Context, arg TouchDaemonParams) error {
	_, err := q.db.Exec(ctx, touchDaemon,
		arg.TokenID,
		arg.ProjectID,
		arg.Hostname,
		arg.Version,
	)
	return err
}
